import csv,hashlib,json
from pathlib import Path
task=Path('task_memory/task_2026-10-15_glm53_dsv4_vllm028_h800')
root=task/'h3o_operator_costs/a6_forward_attention_20261101'
paths={'current_a6':task/'h3o_operator_costs/a6_codex_20261101/result.json','median3_a6':root/'median3_a6/result.json','current_forward':root/'current_phase_heldout.json','median3_forward':root/'median3_forward_attention.json'}
loaded={key:json.loads(path.read_text()) for key,path in paths.items()}
old,new=loaded['current_a6'],loaded['median3_a6']
assert old['attention']['fold_assignment']==new['attention']['fold_assignment']
assert len(new['attention']['fold_assignment'])==1421
assert old['gate_thresholds']==new['gate_thresholds']
assert old['config']['input_sha256']==new['config']['input_sha256']
c,m=loaded['current_forward'],loaded['median3_forward']
assert c['folds']==m['folds']=={'folds':5,'seed':1234}
assert c['limits']==m['limits']=={'median':0.05,'p90':0.1}
assert c['coverage_skips']==m['coverage_skips']
assert c['attention']['omissions']==m['attention']['omissions']
assert c['attention']['layer_group_counts']==m['attention']['layer_group_counts']
assert c['attention']['complete_workloads']==m['attention']['complete_workloads']==1373
assert c['attention']['omitted_workloads']==m['attention']['omitted_workloads']==48
assert c['attention']['attention_verdict']==m['attention']['attention_verdict']=='NOT_EVALUABLE'
assert c['attention']['e2e_acceptance']==m['attention']['e2e_acceptance']=='NOT_ASSESSED'
current={r['unit_id']:r for r in c['attention']['workloads']}
measured={r['unit_id']:r for r in m['attention']['workloads']}
assert current.keys()==measured.keys()
for unit_id,row in measured.items():
    original=current[unit_id]
    for key in ('fold','workload','case_ids','row_indices','source_row_count','expected_layer_groups','present_layer_groups','layer_count','measured_attention_us'):
        assert original[key]==row[key],(unit_id,key)
    assert row['measured_attention_us']>0
    assert abs(row['absolute_relative_error']-abs(row['predicted_attention_us']-row['measured_attention_us'])/row['measured_attention_us'])<1e-12
sources={key:{'path':str(path.resolve()),'sha256':hashlib.sha256(path.read_bytes()).hexdigest()} for key,path in paths.items()}
for command_name,source_name in (('median3_a6_command.json','median3_a6'),('median3_forward_command.json','median3_forward')):
    command=json.loads((root/command_name).read_text())
    assert command['status']=='FINISHED' and command['exit_code']==0
    assert command['result_sha256' if source_name=='median3_a6' else 'output_sha256']==sources[source_name]['sha256']
table=Path(m['input_table']['path'])
assert hashlib.sha256(table.read_bytes()).hexdigest()==m['input_table']['sha256']==new['input_table']['sha256']
groups=[]
old_groups={tuple(g['key']):g for g in c['attention']['by_group']}
for g in m['attention']['by_group']:
    previous=old_groups[tuple(g['key'])]
    assert g['count']==previous['count'] and g['omitted_workloads']==previous['omitted_workloads']
    rows=[r for r in measured.values() if [r['workload']['graph_runtime_mode'],r['workload']['phase']]==g['key']]
    groups.append({'key':g['key'],'reference':previous,'median3':g,'maximum_absolute_relative_error':max((r['absolute_relative_error'] for r in rows),default=None),'maximum_absolute_error_us':max((abs(r['signed_error_us']) for r in rows),default=None),'p90_change_percentage_points':None if not rows else 100*(g['p90_absolute_relative_error']-previous['p90_absolute_relative_error'])})
    if rows: assert g['verdict']=='PASS' and g['rows_above_10_percent']==0
scope_summary={}
for label,r in (('reference',old),('median3',new)):
    scope_summary[label]={name:{mode:{'verdict':entry[mode]['verdict'],'kernel_time_relative_error':entry[mode]['kernel_time_relative_error'],'combined_time_relative_error':entry[mode]['combined_time_relative_error']} for mode in ('joint','per_column')} for name,entry in r['attention']['per_scope'].items()}
report={'status':'PASS_VERIFICATION_WITH_UNQUALIFIED_OMISSIONS','sources':sources,'input_table':m['input_table'],'fold_assignment_equal':True,'fold_count':5,'seed':1234,'limits':m['limits'],'all_1421_workload_coordinates_and_fold_ids_equal':True,'all_1373_measured_references_and_layer_weights_equal':True,'all_182_row_skips_and_48_workload_omissions_equal':True,'evaluated_rows':m['evaluated_rows'],'total_rows':m['total_rows'],'attention_verdict':m['attention']['attention_verdict'],'e2e_acceptance':m['attention']['e2e_acceptance'],'complete_workloads':1373,'omitted_workloads':48,'groups':groups,'scope_diagnostics':scope_summary,'method_limit':'Median3 changes kernel-time medians only; gaps and measured-window reference remain the original generation. Independent replay passes change all timing statistics together.'}
with (root/'median3_verification.json').open('x') as stream: json.dump(report,stream,indent=2,allow_nan=False)
with (root/'median3_forward_workloads.csv').open('x',newline='') as stream:
    writer=csv.writer(stream)
    writer.writerow(['unit_id','fold','graph_runtime_mode','phase','layer_count','measured_attention_us','reference_predicted_attention_us','median3_predicted_attention_us','median3_signed_error_us','median3_absolute_relative_error'])
    for unit_id,row in sorted(measured.items()):
        writer.writerow([unit_id,row['fold'],row['workload']['graph_runtime_mode'],row['workload']['phase'],row['layer_count'],row['measured_attention_us'],current[unit_id]['predicted_attention_us'],row['predicted_attention_us'],row['signed_error_us'],row['absolute_relative_error']])
summary={key:value for key,value in report.items() if key not in ('scope_diagnostics','groups')}
summary['groups']=[{'key':g['key'],'count':g['median3']['count'],'verdict':g['median3']['verdict'],'median_pct':None if not g['median3']['count'] else 100*g['median3']['median_absolute_relative_error'],'p90_pct':None if not g['median3']['count'] else 100*g['median3']['p90_absolute_relative_error'],'signed_mean_pct':None if not g['median3']['count'] else 100*g['median3']['signed_mean_relative_error'],'max_pct':None if not g['median3']['count'] else 100*g['maximum_absolute_relative_error'],'p90_change_percentage_points':g['p90_change_percentage_points']} for g in groups]
with (root/'median3_summary.json').open('x') as stream: json.dump(summary,stream,indent=2,allow_nan=False)
print(json.dumps({key:summary[key] for key in ('status','fold_assignment_equal','complete_workloads','omitted_workloads','attention_verdict','groups')}))
